/**
 * Shidashi - Bootstrap 5 / bslib dashboard toolkit
 *
 * jQuery is used for Shiny output bindings (find() must return jQuery objects)
 * and for Shiny custom events (shiny:connected is a jQuery event).
 * jQuery is provided by Shiny at runtime and treated as external by esbuild.
 */

import $ from 'jquery';
import ClipboardJS from 'clipboard';
import { IFrameManager } from './iframe-manager.js';
import { Sidebar } from './sidebar.js';
import { registerOutputBindings } from './output-bindings.js';
import { getConversationMarkdown, injectCodeCopyButtons, showToast } from './chat-helpers.js';
import { captureVisualContent } from './canvas-capture.js';

// ============================================================================
// Shidashi Main Class
// ============================================================================

class ShidashiApp {
  constructor() {
    this._shiny = null;
    this._dummy = document.createElement('div');
    this._dummy2 = document.createElement('div');
    this._localStorage = window.localStorage;
    this._sessionStorage = window.sessionStorage;
    this._keyPrefix = 'shidashi-session-';
    this._keyNotification = 'shidashi-session';
    this._keyTheme = 'shidashi-theme';
    this._listeners = {};
    this._storageDuration = 1000 * 60 * 60 * 24; // 1 day (matches original)
    this.sessionData = {};
    this._initialized = false;
    this._shiny_registered = false;
    this.shiny_connected = false;
    this._shiny_callstacks = [];
    this.sidebar = null;
    this.iframeManager = null;
    this._toastCounter = 0;

    // RAVE-specific state
    this._moduleId = undefined;
    this._active_module = undefined;
    this._bodyClasses = [];
    this.variableBodyClasses = ['scroller-not-top', 'navbar-hidden'];
  }

  // ---------- Shiny helper ----------

  ensureShiny(then) {
    if (!this._shiny) {
      this._shiny = window.Shiny;
    }
    if (typeof then === 'function') {
      this._shiny_callstacks.push(then);
    }
    if (document.readyState && document.readyState === 'complete' &&
        this._shiny && this.shiny_connected) {
      while (this._shiny_callstacks.length > 0) {
        const f = this._shiny_callstacks.shift();
        try {
          f(this._shiny);
        } catch (e) {
          console.warn(e);
        }
      }
    }
  }

  bindAll(el, ensure = true) {
    const b = (shiny) => {
      shiny.bindAll(el);
      // Also report active tabs in any tabsets within el
      const tabLists = (el instanceof HTMLElement ? el : document).querySelectorAll('.card-tabs [role="tablist"]');
      for (let ii = 0; ii < tabLists.length; ii++) {
        const pa = tabLists[ii];
        if (pa && pa.id) {
          const activeTab = pa.querySelector('li.nav-item > .nav-link.active');
          if (activeTab) {
            shiny.setInputValue(pa.id, activeTab.textContent);
          }
        }
      }
    };
    if (ensure || this._shiny) {
      this.ensureShiny(b);
    }
  }

  unbindAll(el, ensure = true) {
    const ub = (shiny) => {
      shiny.unbindAll(el);
    };
    if (ensure || this._shiny) {
      this.ensureShiny(ub);
    }
  }

  // ---------- localStorage session sync ----------

  fromLocalStorage(key, defaultIfNotFound, ignoreDuration = false) {
    try {
      const item = JSON.parse(this._localStorage.getItem(key));
      item.last_saved = new Date(item.last_saved);
      item._key = key;
      if (!ignoreDuration) {
        const now = new Date();
        if (now - item.last_saved > this._storageDuration) {
          console.debug('Removing expired key: ' + key);
          this._localStorage.removeItem(key);
        } else {
          return item;
        }
      } else {
        return item;
      }
    } catch (e) {
      console.debug('Removing corrupted key: ' + key);
      this._localStorage.removeItem(key);
    }
    if (defaultIfNotFound === true) {
      return {
        inputs: {},
        last_saved: new Date(),
        last_edit: this._private_id,
        inputs_changed: [],
        _key: key
      };
    }
    return defaultIfNotFound;
  }

  async cleanLocalStorage(maxEntries = 1000) {
    const items = [];
    for (let key in this._localStorage) {
      if (key.startsWith(this._keyPrefix)) {
        const item = this.fromLocalStorage(key);
        if (maxEntries && item) {
          items.push(item);
        }
      }
    }
    if (items.length && items.length > maxEntries) {
      items.sort((v1, v2) => v1.last_saved > v2.last_saved ? 1 : -1);
      items.splice(items.length - maxEntries);
      items.forEach((item) => {
        this._localStorage.removeItem(item._key);
      });
    }
  }

  _setSharedId(shared_id) {
    if (typeof this._shared_id !== 'string' && typeof shared_id === 'string') {
      this._shared_id = shared_id;
      this._storage_key = this._keyPrefix + this._shared_id;
    }
    return this._storage_key;
  }

  _setPrivateId(private_id) {
    if (typeof this._private_id !== 'string') {
      if (typeof private_id === 'string') {
        this._private_id = private_id;
      } else {
        this._private_id = Math.random().toString(16).substr(2, 8);
      }
    }
    return this._private_id;
  }

  broadcastSessionData(shared_id, private_id) {
    const storage_key = this._setSharedId(shared_id);
    if (!storage_key) return;
    const private_id_ = this._setPrivateId(private_id);

    const keys_changed = Object.keys(this.sessionData);
    if (!keys_changed.length) return;

    const now = new Date();
    const stored = this.fromLocalStorage(storage_key, true, true);
    stored.last_saved = now;
    stored.last_edit = private_id_;
    stored.inputs_changed = keys_changed;
    for (let k in this.sessionData) {
      stored.inputs[k] = this.sessionData[k];
    }
    this._localStorage.setItem(storage_key, JSON.stringify(stored));
    this._localStorage.setItem(this._keyNotification, JSON.stringify({
      storage_key: storage_key,
      private_id: private_id_,
      last_saved: now
    }));
  }

  // ---------- Active module reporting ----------

  /**
   * Report the currently active module to Shiny via @shidashi_active_module@ input.
   * Called from IFrameManager.activateTab(), set_current_module handler, and
   * standalone module initialization.
   * @param {string} moduleId - The module identifier
   */
  _reportActiveModule(moduleId) {
    if (!moduleId) return;
    this._activeModuleId = moduleId;
    this.ensureShiny(() => {
      if (typeof this._shiny.onInputChange !== 'function') return;
      this._shiny.onInputChange('@shidashi_active_module@', {
        module_id: moduleId,
        token: this._sessionToken || null,
        timestamp: Date.now()
      });
    });
  }

  /**
   * Show a module in this dashboard, as clicking it in the sidebar does.
   * @param {string} moduleId
   * @param {boolean} autoNew - open a new tab when the module is not open
   * @returns {string} a status from IFrameManager.showModule(), or
   *   'no_dashboard' on a page without tabs
   */
  switchModule(moduleId, autoNew = true, title) {
    if (!this.iframeManager) return 'no_dashboard';
    const status = this.iframeManager.showModule(moduleId, autoNew, title);
    if (status === 'activated' || status === 'opened') {
      if (this.sidebar) this.sidebar.setActiveByModule(moduleId);
      this._reportActiveModule(moduleId);
    }
    return status;
  }

  /**
   * The app of the dashboard that shows this page: this page (the
   * dashboard), or the parent frame of a module page in a tab (same
   * origin); null when there is none.
   */
  _dashboardApp() {
    if (this.iframeManager) return this;
    if (window.self === window.top) return null;
    try {
      const app = window.parent.shidashi;
      if (app && app.iframeManager && typeof app.switchModule === 'function') {
        return app;
      }
    } catch (e) { /* cross-origin */ }
    return null;
  }

  // ---------- AI agent targeting (MCP) ----------

  /**
   * Tell Shiny that the user is using this module page, so AI agent tool
   * calls without an explicit target run here. Reported on interaction
   * (throttled), when the dashboard shell activates this tab, and on load
   * when the page is visible. Module pages only; the shell is not a target.
   */
  _initFocusReporting() {
    let lastReport = 0;
    const report = (force) => {
      const now = Date.now();
      if (!force && now - lastReport < 2000) return;
      lastReport = now;
      this.ensureShiny((shiny) => {
        shiny.setInputValue('@shidashi_focus@', now, { priority: 'event' });
      });
    };
    ['pointerdown', 'keydown', 'focusin'].forEach((type) => {
      document.addEventListener(type, () => report(false),
                                { capture: true, passive: true });
    });
    window.addEventListener('message', (evt) => {
      if (evt.origin !== window.location.origin) return;
      if (evt.data?.type === 'shidashi.module_activated') report(true);
    });
    // Hidden iframes (inactive tabs) have no size
    if (document.visibilityState === 'visible' &&
        window.innerWidth > 0 && window.innerHeight > 0) {
      report(true);
    }
  }

  /**
   * Show the pin toggle and reflect its state. A pinned tab receives AI
   * agent tool calls even when the user works in another tab; pinning one
   * tab unpins the others (handled in R).
   *
   * A `.btn-ai-pin` placeholder already on the page (e.g. the hidden one in
   * the ravedash footer's Controllers menu) is used when present; otherwise
   * the toggle is added next to the floating buttons.
   */
  _setAiPinState(pinned) {
    let btn = document.querySelector('.btn-ai-pin');
    if (!btn) {
      let container = document.querySelector('.shidashi-back-to-top');
      if (!container) {
        container = document.createElement('div');
        container.className = 'shidashi-back-to-top';
        document.body.appendChild(container);
      }
      btn = document.createElement('a');
      btn.href = '#';
      btn.className = 'btn btn-default btn-ai-pin';
      btn.setAttribute('role', 'button');
      btn.innerHTML = '<i class="fas fa-thumbtack" aria-hidden="true"></i>';
      container.appendChild(btn);
    }
    if (!btn.dataset.shidashiPinBound) {
      btn.dataset.shidashiPinBound = 'true';
      btn.addEventListener('click', (evt) => {
        evt.preventDefault();
        const next = !btn.classList.contains('active');
        this.ensureShiny((shiny) => {
          shiny.setInputValue('@shidashi_ai_pin@', next, { priority: 'event' });
        });
      });
    }
    // Placeholders ship hidden: only pages with agent tools get this message
    btn.hidden = false;
    btn.classList.toggle('active', !!pinned);
    btn.setAttribute('aria-pressed', pinned ? 'true' : 'false');
    document.body.classList.toggle('shidashi-ai-pinned', !!pinned);

    const label = pinned
      ? 'AI agent tool calls run in this tab. Click to unpin.'
      : 'Pin this tab: AI agent tool calls will run here.';
    btn.setAttribute('aria-label', label);
    // A Bootstrap tooltip keeps its own copy of the title
    const tooltip = window.bootstrap?.Tooltip?.getInstance(btn);
    if (tooltip) {
      btn.setAttribute('data-bs-original-title', label);
      tooltip.setContent({ '.tooltip-inner': label });
    } else {
      btn.title = label;
    }
  }

  // ---------- Event system ----------

  broadcastEvent(type, message = {}) {
    const event = new CustomEvent('shidashi-event-' + type, { detail: message });
    this._dummy.dispatchEvent(event);
    this.ensureShiny(() => {
      if (typeof this._shiny.onInputChange !== 'function') return;
      this._shiny.onInputChange('@shidashi_event@', {
        type: type,
        message: message,
        shared_id: this._shared_id,
        private_id: this._private_id
      });
    });
    // Propagate to managed iframes
    if (this.iframeManager) {
      this.iframeManager.notifyIframes(type, message);
    }
  }

  registerListener(type, callback, replace = true) {
    const event_str = 'shidashi-event-' + type;
    if (replace) {
      const old_function = this._listeners[type];
      if (typeof old_function === 'function') {
        this._dummy.removeEventListener(event_str, old_function);
      }
    }
    if (typeof callback === 'function') {
      const cb_ = (evt) => callback(evt.detail);
      this._dummy.addEventListener(event_str, cb_);
      this._listeners[type] = cb_;
    }
  }

  // ---------- Theme ----------

  _col2Hex(color, fallback) {
    let col = color.trim();
    if (col.length < 4) return fallback || '#000000';
    if (col[0] === '#') {
      if (col.length === 7) return col;
      col = '#' + col[1] + col[1] + col[2] + col[2] + col[3] + col[3];
      return col;
    }
    // Handle rgba with alpha=0 (transparent) — return fallback
    const rgbaMatch = col.match(/rgba\((\d+),\s*(\d+),\s*(\d+),\s*([\d.]+)\)/);
    if (rgbaMatch && parseFloat(rgbaMatch[4]) === 0) {
      return fallback || '#ffffff';
    }
    let parts = col.match(/rgb[a]?\((\d+),\s*(\d+),\s*(\d+)[\),]/);
    if (!parts) return fallback || '#000000';
    delete parts[0];
    for (let i = 1; i <= 3; ++i) {
      parts[i] = parseInt(parts[i]).toString(16);
      if (parts[i].length === 1) parts[i] = '0' + parts[i];
    }
    col = '#' + parts.slice(1, 4).join('');
    return col;
  }

  _reportTheme(mode) {
    if (typeof mode !== 'string') {
      mode = this.isDarkMode() ? 'dark' : 'light';
    }
    const darkFallbackBg = '#343a40';
    const lightFallbackBg = '#ffffff';
    const darkFallbackFg = '#e9ecef';
    const lightFallbackFg = '#343a40';
    const background = mode === 'dark' ? darkFallbackBg : lightFallbackBg;
    const foreground = mode === 'dark' ? darkFallbackFg : lightFallbackFg;

    this.broadcastEvent('theme.changed', {
      theme: mode,
      mode: mode,
      background: background,
      foreground: foreground
    });
  }

  _updateThemeIcon(mode) {
    const icon = document.querySelector('[data-shidashi-action="theme-toggle"] i');
    if (!icon) return;
    if (mode === 'dark') {
      icon.classList.remove('fa-moon');
      icon.classList.add('fa-sun');
    } else {
      icon.classList.remove('fa-sun');
      icon.classList.add('fa-moon');
    }
  }

  isDarkMode() {
    return document.body.classList.contains('dark-mode');
  }

  asLightMode() {
    document.body.classList.remove('dark-mode');
    // Sidebar stays dark by default in light mode (rave-pipelines convention)
    // Only switch to sidebar-light if the sidebar has the explicit opt-in class
    const aside = document.querySelector('.shidashi-sidebar');
    if (aside && aside.classList.contains('shidashi-sidebar--follow-theme')) {
      aside.classList.remove('sidebar-dark');
      aside.classList.add('sidebar-light');
    }
    // Header navbar theme
    const header = document.querySelector('.shidashi-header');
    if (header) {
      header.setAttribute('data-bs-theme', 'light');
    }
    this._updateThemeIcon('light');
    this._sessionStorage.setItem(this._keyTheme, 'light');
    // Propagate to iframes
    if (this.iframeManager) {
      this.iframeManager.propagateThemeToAll();
    }
    this._reportTheme('light');
  }

  asDarkMode() {
    document.body.classList.add('dark-mode');
    const aside = document.querySelector('.shidashi-sidebar');
    if (aside) {
      aside.classList.remove('sidebar-light');
      aside.classList.add('sidebar-dark');
    }
    // Header navbar theme
    const header = document.querySelector('.shidashi-header');
    if (header) {
      header.setAttribute('data-bs-theme', 'dark');
    }
    this._updateThemeIcon('dark');
    this._sessionStorage.setItem(this._keyTheme, 'dark');
    if (this.iframeManager) {
      this.iframeManager.propagateThemeToAll();
    }
    this._reportTheme('dark');
  }

  // ---------- UI actions ----------

  click(selector) {
    if (!selector || selector === '') return;
    const el = document.querySelector(selector);
    if (el) el.click();
  }

  triggerResize(timeout) {
    if (timeout) {
      setTimeout(() => this.triggerResize(), timeout);
    } else {
      window.dispatchEvent(new Event('resize'));
      this.ensureShiny(() => {
        this._shiny.unbindAll(this._dummy2);
      });
    }
  }

  // ---------- Tabset (card-tabset) ----------

  tabsetAdd(inputId, title, body, active = true) {
    const el = document.getElementById(inputId);
    const elbody = document.getElementById(inputId + 'Content');
    if (!el) return 'Cannot find tabset with given settings.';
    if (!elbody) return 'Cannot find tabset with given settings.';

    // Check for duplicate title
    const existingHeaders = el.querySelectorAll(':scope > .nav-item.nav-tab-header');
    for (const item of existingHeaders) {
      const link = item.querySelector('.nav-link');
      if (link && link.textContent === title) {
        return "A tab with title '" + title + "' already exists.";
      }
    }

    const tabId = Math.random().toString(16).substr(2, 8);

    // Create header
    const headerItem = document.createElement('li');
    headerItem.className = 'nav-item nav-tab-header';
    const headerA = document.createElement('a');
    headerA.className = 'nav-link';
    headerA.setAttribute('href', `#${inputId}-${tabId}`);
    headerA.setAttribute('id', `${inputId}-${tabId}-tab`);
    headerA.setAttribute('data-bs-toggle', 'tab');
    headerA.setAttribute('role', 'tab');
    headerA.setAttribute('aria-controls', `${inputId}-${tabId}`);
    headerA.setAttribute('aria-selected', 'false');
    headerA.textContent = title;
    headerItem.appendChild(headerA);

    // Insert after last header
    if (existingHeaders.length > 0) {
      existingHeaders[existingHeaders.length - 1].after(headerItem);
    } else {
      el.appendChild(headerItem);
    }

    // Create body pane
    const bodyEl = document.createElement('div');
    bodyEl.className = 'tab-pane fade';
    bodyEl.setAttribute('id', `${inputId}-${tabId}`);
    bodyEl.setAttribute('role', 'tabpanel');
    bodyEl.setAttribute('tab-index', tabId);
    bodyEl.setAttribute('aria-labelledby', `${inputId}-${tabId}-tab`);
    bodyEl.innerHTML = body;
    elbody.appendChild(bodyEl);

    this.bindAll(elbody);

    if (active) {
      return this.tabsetActivate(inputId, title);
    }
    return true;
  }

  tabsetRemove(inputId, title) {
    const el = document.getElementById(inputId);
    const elbody = document.getElementById(inputId + 'Content');
    if (!el) return 'Cannot find tabset with given settings.';
    if (!elbody) return 'Cannot find tabset with given settings.';

    const existingItems = el.querySelectorAll(':scope > .nav-item.nav-tab-header');
    if (!existingItems.length) {
      return "Tab with title '" + title + "' cannot be found.";
    }

    let found = false;
    let activate = false;
    let removeIdx = -1;

    existingItems.forEach((item, i) => {
      const link = item.querySelector('.nav-link');
      if (link && link.textContent === title) {
        found = true;
        removeIdx = i;
        const tabid = link.getAttribute('aria-controls');
        const tab = document.getElementById(tabid);
        const isActive = link.getAttribute('aria-selected');
        this.unbindAll(tab);
        item.remove();
        if (tab) tab.remove();
        if (isActive === 'true') {
          activate = true;
        }
      }
    });

    if (!found) {
      return "A tab with title '" + title + "' cannot be found.";
    }

    if (activate && existingItems.length > 1) {
      let activeTab;
      if (removeIdx - 1 >= 0) {
        activeTab = existingItems[removeIdx - 1];
      } else {
        activeTab = existingItems[removeIdx + 1];
      }
      if (activeTab) {
        const link = activeTab.querySelector('a.nav-link');
        if (link) link.click();
      }
    }
    return true;
  }

  tabsetActivate(inputId, title) {
    const el = document.getElementById(inputId);
    const elbody = document.getElementById(inputId + 'Content');
    if (!el) return 'Cannot find tabset with given settings.';
    if (!elbody) return 'Cannot find tabset with given settings.';

    const existingItems = el.querySelectorAll(':scope > .nav-item.nav-tab-header');
    if (!existingItems.length) {
      return "Tab with title '" + title + "' cannot be found.";
    }

    let activated = false;
    existingItems.forEach((item) => {
      const link = item.querySelector('.nav-link');
      if (!link) return;
      const paneId = link.getAttribute('aria-controls');
      const pane = paneId ? document.getElementById(paneId) : null;
      if (link.textContent === title) {
        link.click();
        activated = true;
      } else {
        link.classList.remove('active');
        link.setAttribute('aria-selected', 'false');
        if (pane) {
          pane.classList.remove('show', 'active');
        }
      }
    });

    if (!activated) {
      return "Tab with title '" + title + "' cannot be found.";
    }
    return true;
  }

  // ---------- Card / card2 / flip-box ----------

  card(inputId, method) {
    // ravedash may call with a single object: {selector, method}
    if (typeof inputId === 'object' && inputId !== null) {
      const opts = inputId;
      if (opts.selector) {
        document.querySelectorAll(opts.selector).forEach((el) => {
          const card = el.closest('.card') || el;
          this._cardOperate(card, opts.method);
        });
        return;
      }
    }
    const el = document.getElementById(inputId);
    if (!el) return;
    const card = el.closest('.card') || el;
    this._cardOperate(card, method);
  }

  _cardOperate(card, method) {
    if (!card) return;
    switch (method) {
      case 'collapse':
        // CSS on .card.shidashi-collapsed handles the soft-hide:
        // height:0 + overflow:hidden keeps the element in the DOM so
        // Shiny outputs retain defined width and continue to update.
        card.classList.add('shidashi-collapsed');
        this._updateCardIcon(card, true);
        break;

      case 'minimize':
        // Reverse of maximize: restore the card from fullscreen
        card.classList.remove('shidashi-maximized');
        document.body.classList.remove('shidashi-card-maximized');
        this._updateMaximizeIcon(card);
        this.triggerResize(50);
        break;

      case 'expand':
        card.classList.remove('shidashi-collapsed');
        if (card.classList.contains('start-collapsed')) {
          this.unbindAll(card);
          card.classList.remove('start-collapsed');
          this.bindAll(card);
        }
        this._updateCardIcon(card, false);
        this.triggerResize(50);
        break;

      case 'maximize':
        card.classList.add('shidashi-maximized');
        document.body.classList.add('shidashi-card-maximized');
        this._updateMaximizeIcon(card);
        this.triggerResize(50);
        break;

      case 'toggleMaximize':
        if (method === 'toggleMaximize' && card.classList.contains('shidashi-maximized')) {
          card.classList.remove('shidashi-maximized');
          document.body.classList.remove('shidashi-card-maximized');
        } else {
          card.classList.add('shidashi-maximized');
          document.body.classList.add('shidashi-card-maximized');
        }
        this._updateMaximizeIcon(card);
        this.triggerResize(50);
        break;

      case 'restore':
        card.classList.remove('shidashi-maximized');
        document.body.classList.remove('shidashi-card-maximized');
        this._updateMaximizeIcon(card);
        this.triggerResize(50);
        break;

      case 'toggle':
        if (card.classList.contains('shidashi-collapsed') || card.classList.contains('start-collapsed')) {
          this._cardOperate(card, 'expand');
        } else {
          this._cardOperate(card, 'collapse');
        }
        break;

      case 'remove':
        card.remove();
        break;

      default:
        break;
    }
  }

  _updateCardIcon(card, collapsed) {
    const icon = card.querySelector('[data-card-widget="collapse"] i, [data-card-widget="collapse"] .fas');
    if (icon) {
      if (collapsed) {
        icon.classList.remove('fa-minus');
        icon.classList.add('fa-plus');
      } else {
        icon.classList.remove('fa-plus');
        icon.classList.add('fa-minus');
      }
    }
  }

  _updateMaximizeIcon(card) {
    const btn = card.querySelector('[data-card-widget="maximize"]');
    if (!btn) return;
    const icon = btn.querySelector('i, .fas');
    if (icon) {
      if (card.classList.contains('shidashi-maximized')) {
        icon.classList.remove('fa-expand');
        icon.classList.add('fa-compress');
      } else {
        icon.classList.remove('fa-compress');
        icon.classList.add('fa-expand');
      }
    }
  }

  toggleCard2(selector) {
    const el = document.querySelector(selector);
    if (!el) return;
    // Match original AdminLTE3 behavior: click the button to trigger DirectChat toggle
    el.click();
  }

  flipBox(inputId) {
    const el = document.getElementById(inputId);
    if (el && el.classList.contains('flip-box')) {
      el.classList.toggle('active');
    }
  }

  // ---------- Notification (BS5 Toast) ----------

  createNotification(options) {
    const container = this._getToastContainer();
    const id = 'shidashi-toast-' + (++this._toastCounter);

    const toastEl = document.createElement('div');
    toastEl.id = id;
    toastEl.className = 'toast';
    toastEl.setAttribute('role', 'alert');
    toastEl.setAttribute('aria-live', 'assertive');
    toastEl.setAttribute('aria-atomic', 'true');

    if (options.class) {
      toastEl.classList.add(...options.class.split(/\s+/));
    }
    if (options.autohide === false) {
      toastEl.setAttribute('data-bs-autohide', 'false');
    } else {
      toastEl.setAttribute('data-bs-autohide', 'true');
      toastEl.setAttribute('data-bs-delay', String(options.delay || 5000));
    }

    // Build toast content
    let headerHtml = '';
    if (options.icon) {
      headerHtml += `<i class="${options.icon} me-2"></i>`;
    }
    if (options.image) {
      headerHtml += `<img src="${this._escapeAttr(options.image)}" class="rounded me-2" alt="" style="width:20px;height:20px;">`;
    }
    headerHtml += `<strong class="me-auto">${this._escapeHtml(options.title || '')}</strong>`;
    if (options.subtitle) {
      headerHtml += `<small>${this._escapeHtml(options.subtitle)}</small>`;
    }

    toastEl.innerHTML = `
      <div class="toast-header">
        ${headerHtml}
        <button type="button" class="btn-close" data-bs-dismiss="toast" aria-label="Close"></button>
      </div>
      ${options.body ? `<div class="toast-body">${options.body}</div>` : ''}
    `;

    container.appendChild(toastEl);

    // Bind Shiny outputs inside toast
    this.ensureShiny(() => {
      this._shiny.bindAll(toastEl);
    });

    // Show via BS5 Toast API
    if (window.bootstrap?.Toast) {
      const toast = new bootstrap.Toast(toastEl);
      toast.show();

      // Remove from DOM after hidden
      toastEl.addEventListener('hidden.bs.toast', () => {
        this.ensureShiny(() => {
          this._shiny.unbindAll(toastEl);
        });
        toastEl.remove();
      });
    }
  }

  clearNotification(selector) {
    const els = document.querySelectorAll(selector || '.toast');
    els.forEach(el => {
      if (window.bootstrap?.Toast) {
        const instance = bootstrap.Toast.getInstance(el);
        if (instance) {
          instance.hide();
          return;
        }
      }
      el.remove();
    });
  }

  _getToastContainer() {
    let container = document.getElementById('shidashi-toast-container');
    if (!container) {
      container = document.createElement('div');
      container.id = 'shidashi-toast-container';
      container.className = 'toast-container position-fixed top-0 end-0 p-3';
      container.style.zIndex = '1100';
      document.body.appendChild(container);
    }
    return container;
  }

  // ---------- Progress ----------

  setProgress(inputId, value, max = 100, description = null) {
    if (typeof value !== 'number' || isNaN(value)) return;
    const el = document.getElementById(inputId);
    if (!el) return;

    let v = parseInt(value / max * 100);
    v = Math.max(0, Math.min(100, v));
    const bar = el.querySelector('.progress-bar');
    if (bar) bar.style.width = v + '%';
    if (typeof description === 'string') {
      const desc = el.querySelector('.progress-description.progress-message');
      if (desc) desc.textContent = description;
    }
  }

  // ---------- RAVE helpers ----------

  shinySetInput(inputId, value, add_timestamp = true, children = false) {
    this.ensureShiny((shiny) => {
      if (add_timestamp) {
        value.timestamp = new Date();
      }
      value._active_module = this._active_module;
      value.parent_frame = document.body.classList.contains('parent-frame');
      shiny.setInputValue(inputId, value);

      console.debug(`[shidashi] shiny input [${inputId}] <- ${JSON.stringify(value)}`);

      if (children && this.iframeManager) {
        // Clone the base payload (without parent-specific fields) so each
        // child can enrich it with its own _active_module & parent_frame.
        const baseValue = Object.assign({}, value);
        delete baseValue._active_module;
        delete baseValue.parent_frame;
        delete baseValue.timestamp;

        this.iframeManager._tabs.forEach(entry => {
          try {
            const win = entry.iframe.contentWindow;
            if (win?.shidashi) {
              // Use the child's shinySetInput so _active_module and
              // parent_frame are set from the child's own context.
              win.shidashi.shinySetInput(
                inputId,
                Object.assign({}, baseValue),
                add_timestamp,
                false
              );
            } else if (win?.Shiny?.setInputValue) {
              // Fallback: child doesn't have shidashi, set directly
              const childValue = Object.assign({}, baseValue);
              if (add_timestamp) { childValue.timestamp = new Date(); }
              childValue.parent_frame = false;
              win.Shiny.setInputValue(inputId, childValue);
            }
          } catch (e) { /* cross-origin safety */ }
        });
      }
    });
  }

  openURL(url, target = '_blank') {
    const link = document.createElement('a');
    link.setAttribute('target', target);
    link.setAttribute('href', url);
    link.click();
    this.createNotification({
      title: 'Opening the link',
      autohide: true,
      delay: 10000,
      icon: 'fas fa-link',
      subtitle: 'Link created',
      body: `A new window with the given link has been opened. If you haven't seen it, please <a href="${url}" target="${target}">click here</a>.`
    });
  }

  launchStandaloneViewer(outputId) {
    const token = this._sessionToken || '';
    const url = `?module=standalone_viewer&outputId=${encodeURIComponent(outputId)}&token=${encodeURIComponent(token)}`;
    this.openURL(url);
  }

  addClass(selector, cls) {
    document.querySelectorAll(selector).forEach(el => {
      el.classList.add(...cls.split(/\s+/).filter(Boolean));
    });
    if (selector.startsWith('body')) {
      this._bodyClasses = document.body.classList;
    }
  }

  removeClass(selector, cls) {
    document.querySelectorAll(selector).forEach(el => {
      el.classList.remove(...cls.split(/\s+/).filter(Boolean));
    });
    if (selector.startsWith('body')) {
      this._bodyClasses = document.body.classList;
    }
  }

  setInnerHtml(selector, content) {
    const els = document.querySelectorAll(selector);
    els.forEach(el => {
      this.unbindAll(el, false);
      el.innerHTML = content;
      this.bindAll(el, false);
    });
  }

  notifyParent(method, args) {
    if (window.parent && window.parent !== window) {
      if (window.parent.shidashi && typeof window.parent.shidashi[method] === 'function') {
        window.parent.shidashi[method](...args);
      }
    }
  }

  notifyIframes(method, args) {
    if (this.iframeManager) {
      this.iframeManager._tabs.forEach(entry => {
        try {
          if (entry.iframe.contentWindow?.shidashi) {
            entry.iframe.contentWindow.shidashi[method](...args);
          }
        } catch (e) {}
      });
    }
  }

  resumeStatus(parentShidashi) {
    if (!parentShidashi) return;
    if (parentShidashi._active_module !== this._moduleId) return;
    this.variableBodyClasses.forEach(cls => {
      if (this._bodyClasses?.contains?.(cls)) {
        parentShidashi.addClass('body', cls);
      } else {
        parentShidashi.removeClass('body', cls);
      }
    });
  }

  // ---------- Scroll ----------

  scrollTop(duration = 200) {
    window.scrollTo({ top: 0, behavior: duration > 0 ? 'smooth' : 'instant' });
  }

  // ---------- Utils ----------

  async matchSelector(el, selector, next, strict = false) {
    if (!el) return;
    const els = document.querySelectorAll(selector);
    if (!els.length) return;

    for (const item of els) {
      if (item === el || (!strict && item.contains(el))) {
        if (typeof next === 'function') {
          return next(item);
        }
        return true;
      }
    }
  }

  shinyHandler(action, callback) {
    if (!this._shiny) {
      if (window.Shiny) {
        this._shiny = window.Shiny;
      } else {
        console.error('Cannot find window.Shiny object. Is R-shiny running?');
        return false;
      }
    }
    this._shiny.addCustomMessageHandler('shidashi.' + action, callback);
  }

  _escapeHtml(str) {
    const div = document.createElement('div');
    div.textContent = str || '';
    return div.innerHTML;
  }

  _escapeAttr(str) {
    return (str || '').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }

  // ---------- Stream fetch ----------

  /**
   * Fetch a binary stream file written by R's stream_to_js() with no cache.
   *
   * Wire format: [ endianFlag: 1 byte ] [ headerLen: 4 bytes uint32 ] [ header: JSON ] [ body ]
   * endianFlag: 0x01 = little-endian
   * header JSON contains at minimum: { data_type: "raw"|"json"|"int32"|"float32"|"float64" }
   *
   * @param {string} id - Stream identifier (matches the id used in R's stream_path())
   * @returns {Promise<{type: string, header: object, data: ArrayBuffer|object|Int32Array|Float32Array|Float64Array}>}
   */
  async fetchStreamData(id) {
    const url = 'stream/' + encodeURIComponent(id) + '.bin?_t=' + Date.now();
    const response = await fetch(url, { cache: 'no-store' });
    if (!response.ok) {
      throw new Error('fetchStreamData: HTTP ' + response.status + ' for stream id "' + id + '"');
    }
    const buffer = await response.arrayBuffer();
    if (buffer.byteLength < 5) {
      throw new Error('fetchStreamData: response too short (' + buffer.byteLength + ' bytes) for stream id "' + id + '"');
    }
    const view = new DataView(buffer);
    const littleEndian = view.getUint8(0) === 0x01;
    const headerLen = view.getUint32(1, littleEndian);
    if (buffer.byteLength < 5 + headerLen) {
      throw new Error('fetchStreamData: truncated header for stream id "' + id + '"');
    }
    const headerBytes = new Uint8Array(buffer, 5, headerLen);
    const header = JSON.parse(new TextDecoder().decode(headerBytes));
    const dataType = header.data_type;
    // body must be copied out of the shared buffer so typed array constructors work on aligned memory
    const bodyBuffer = buffer.slice(5 + headerLen);
    let data;
    switch (dataType) {
      case 'raw':
        data = bodyBuffer;
        break;
      case 'json':
        data = JSON.parse(new TextDecoder().decode(bodyBuffer));
        break;
      case 'uint8':
        data = new Uint8Array(bodyBuffer);
        break;
      case 'int16':
        data = new Int16Array(bodyBuffer);
        break;
      case 'int32':
        data = new Int32Array(bodyBuffer);
        break;
      case 'float32':
        data = new Float32Array(bodyBuffer);
        break;
      case 'float64':
        data = new Float64Array(bodyBuffer);
        break;
      default:
        throw new Error('fetchStreamData: unknown data_type "' + dataType + '" for stream id "' + id + '"');
    }
    return { type: dataType, header, data };
  }

  // ---------- Query UI (MCP) ----------

  /**
   * A size for an output that has no layout (inside a hidden tab or a
   * collapsed card), so shiny can draw it: the width of the nearest
   * ancestor that has a layout, and the output's own height if set in px,
   * else that ancestor's height (within reason).
   */
  _fallbackOutputSize(el) {
    let width = 0;
    let height = 0;
    for (let p = el.parentElement; p && !width; p = p.parentElement) {
      const rect = p.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
    }
    const ownHeight = getComputedStyle(el).height;
    if (/px$/.test(ownHeight) && parseFloat(ownHeight) > 0) {
      height = parseFloat(ownHeight);
    }
    if (!(width >= 100)) width = 600;
    if (!(height >= 200)) height = 400;
    return {
      width: Math.round(width),
      height: Math.round(Math.min(height, 1200))
    };
  }

  /**
   * Resolve true once `el` loses the `recalculating` class, or false after
   * `timeoutMs`.
   */
  _waitRecalculated(el, timeoutMs) {
    return new Promise((resolve) => {
      if (!el.classList.contains('recalculating')) {
        resolve(true);
        return;
      }
      let timer = null;
      const observer = new MutationObserver(() => {
        if (!el.classList.contains('recalculating')) {
          observer.disconnect();
          clearTimeout(timer);
          // shiny drops the class before it renders the value
          setTimeout(() => resolve(true), 50);
        }
      });
      observer.observe(el, { attributes: true, attributeFilter: ['class'] });
      timer = setTimeout(() => {
        observer.disconnect();
        resolve(false);
      }, timeoutMs);
    });
  }

  /**
   * Answer a `query_ui` request for `el`: an image (canvas, data-URI image,
   * or SVG content, composited into one PNG) or the HTML, with a short note
   * for the agent.
   */
  _answerQuery(el, params) {
    // A missing flag (older R) keeps the old behavior: capture images
    const transformImage = params.transform_image !== false;

    // The element's opening tag gives context without repeating its content
    const outer = el.outerHTML;
    const openingTag = outer.slice(0, outer.indexOf('>') + 1);
    const cs = getComputedStyle(el);

    // Why an element may be empty or out of date
    const notes = [];
    const laidOut = el.getClientRects().length > 0;
    if (!laidOut && cs.display !== 'none') {
      if (params.rendered) {
        // `shiny_output_result` rendered it for this request
        notes.push('The output is not shown on the page (it is inside a hidden tab or a collapsed card), but it was rendered for this request. Content that the browser draws, such as canvases or htmlwidgets, may be blank while hidden.');
      } else {
        notes.push('The element is not shown on the page (it is inside a hidden tab or a collapsed card), so it may be empty or out of date.');
      }
    }
    if (el.classList.contains('recalculating')) {
      notes.push('The output is waiting to be recalculated; shiny does not render hidden outputs.');
    }
    if (el.classList.contains('shiny-output-error')) {
      const message = (el.textContent || '').trim().slice(0, 300);
      notes.push('The output shows an error or a message instead of a value' +
                 (message ? ': ' + message : '.'));
    }

    // R trims long HTML (max_chars), so the full content is sent
    const reply = (fields) => {
      const note = notes.concat(fields.note ? [fields.note] : []).join(' ');
      Shiny.setInputValue(params.input_id, Object.assign({
        request_id: params.request_id,
        type: 'html',
        html: '',
        image_data: '',
        image_type: '',
        laid_out: laidOut
      }, fields, { note: note }), { priority: 'event' });
    };

    if (cs.display === 'none') {
      reply({ type: 'hidden', html: el.innerHTML,
              note: 'The element is hidden (display: none). ' + openingTag });
      return;
    }

    const replyHTML = () => {
      const styleNote = 'Computed styles: display=' + cs.display +
        ', width=' + cs.width + ', height=' + cs.height +
        ', visibility=' + cs.visibility + ', overflow=' + cs.overflow +
        ', position=' + cs.position;
      reply({ html: el.innerHTML, note: openingTag + ' ' + styleNote });
    };

    if (!transformImage) {
      replyHTML();
      return;
    }

    // Visible canvases / images / SVGs, composited into one PNG
    captureVisualContent(el).then((visual) => {
      if (visual) {
        reply({ type: 'image', image_data: visual.image_data,
                image_type: visual.image_type,
                note: [visual.note, openingTag].filter(Boolean).join(' ') });
      } else {
        replyHTML();
      }
    }).catch(replyHTML);
  }

  // ---------- Card tool click delegation ----------

  _bindCardTools() {
    document.addEventListener('click', (evt) => {
      // Collapse/expand
      const collapseBtn = evt.target.closest('[data-card-widget="collapse"]');
      if (collapseBtn) {
        evt.preventDefault();
        const card = collapseBtn.closest('.card');
        if (card) this._cardOperate(card, 'toggle');
        return;
      }

      // Maximize/restore
      const maxBtn = evt.target.closest('[data-card-widget="maximize"]');
      if (maxBtn) {
        evt.preventDefault();
        const card = maxBtn.closest('.card');
        if (card) this._cardOperate(card, 'toggleMaximize');
        return;
      }

      // Refresh / loading
      const refreshBtn = evt.target.closest('[data-card-widget="refresh"]');
      if (refreshBtn) {
        evt.preventDefault();
        this.triggerResize(50);
        return;
      }

      // Flip
      const flipBtn = evt.target.closest('[data-card-widget="flip"]');
      if (flipBtn) {
        evt.preventDefault();
        const card = flipBtn.closest('.card');
        if (card) {
          const flipBox = card.querySelector('.flip-box');
          if (flipBox) flipBox.classList.toggle('active');
        }
        return;
      }

      // Remove
      const removeBtn = evt.target.closest('[data-card-widget="remove"]');
      if (removeBtn) {
        evt.preventDefault();
        const card = removeBtn.closest('.card');
        if (card) this._cardOperate(card, 'remove');
        return;
      }

      // Chat toggle (card2)
      const chatBtn = evt.target.closest('[data-shidashi-action="chat-toggle"]');
      if (chatBtn) {
        evt.preventDefault();
        const directChat = chatBtn.closest('.direct-chat');
        if (directChat) directChat.classList.toggle('direct-chat-contacts-open');
        return;
      }

      // Drawer toggle button
      const toggleBtn = evt.target.closest('[data-shidashi-action="drawer-toggle"]') || evt.target.closest('[data-shidashi-action="toggle-drawer"]');
      if (toggleBtn) {
        evt.preventDefault();
        this.drawerToggle();
        return;
      }
    });

    // Double-click flip-box
    document.addEventListener('dblclick', (evt) => {
      this.matchSelector(evt.target, '.flip-box', (item) => {
        const action = item.getAttribute('data-toggle') || item.getAttribute('data-bs-toggle');
        if (action === 'click') {
          item.classList.toggle('active');
        } else if (action === 'click-front') {
          item.classList.add('active');
        }
      });
    });
  }

  // ---------- Initialization ----------

  _finalize_initialization() {
    if (this._initialized) return;
    this._initialized = true;

    // Initialize sidebar
    const sidebarEl = document.querySelector('.shidashi-sidebar');
    if (sidebarEl) {
      this.sidebar = new Sidebar(sidebarEl);
      document.body.classList.add('has-sidebar');
    }

    // Detect iframe context — hide module header when embedded
    if (window.self !== window.top) {
      document.body.classList.add('in-iframe');
    }

    // Listen for postMessage from child iframes (e.g. switch_module)
    if (window.self === window.top) {
      window.addEventListener('message', (evt) => {
        if (evt.origin !== window.location.origin) return;
        const data = evt.data;
        if (data?.type === 'shidashi.switch_module' && data?.module_id) {
          this.switchModule(data.module_id, data.auto_new !== false);
        }
      });
    }

    // Initialize iframe manager
    const iframeContainer = document.querySelector('.shidashi-content');
    if (iframeContainer) {
      this.iframeManager = new IFrameManager(iframeContainer);
    } else {
      // A module page (in an iframe or standalone) can be an AI agent target
      this._initFocusReporting();
    }

    // Restore theme
    const theme = this._sessionStorage.getItem(this._keyTheme);
    if (theme === 'light') {
      this.asLightMode();
    } else if (theme === 'dark') {
      this.asDarkMode();
    } else if (document.body.classList.contains('dark-mode')) {
      // Body starts with dark-mode class from R but no stored preference
      const header = document.querySelector('.shidashi-header');
      if (header) { header.setAttribute('data-bs-theme', 'dark'); }
      this._updateThemeIcon('dark');
    }

    // Dismiss preloader (was handled by AdminLTE in the original)
    this._dismissPreloader();

    // Back-to-top widget
    this._initBackToTop();

    // Card tools delegation
    this._bindCardTools();

    // Initialize custom resize handles for .resize-vertical elements
    this._initResizeHandles();

    // Drawer overlay click → close drawer (use delegation for dynamic content)
    document.addEventListener('click', (e) => {
      if (e.target.classList.contains('shidashi-drawer-overlay')) {
        this.drawerClose();
      }
    });

    // Drawer close-tab click → close drawer (no-overlay mode)
    document.addEventListener('click', (e) => {
      const closeTab = e.target.closest('.shidashi-drawer-close-tab');
      if (closeTab) {
        e.stopPropagation();
        this.drawerClose();
      }
    });

    // Standalone module: when there is no iframe manager and the page
    // is not itself inside an iframe, report the current module from URL
    if (!this.iframeManager && window.self === window.top) {
      const urlParams = new URLSearchParams(window.location.search);
      const moduleId = urlParams.get('module');
      if (moduleId) {
        this._reportActiveModule(moduleId);
      }
    }

    // ------ RAVE-specific click handlers ------

    // .rave-button click → parse rave-action JSON, send to Shiny + broadcast to iframes
    document.addEventListener('click', (evt) => {
      const raveBtn = evt.target.closest('.rave-button[rave-action]');
      if (raveBtn) {
        if (raveBtn.classList.contains('disabled')) { return; }
        evt.preventDefault();
        let action = raveBtn.getAttribute('rave-action');
        if (typeof action === 'string') {
          try {
            action = JSON.parse(action);
            if (typeof action.type !== 'string') {
              console.warn('Cannot parse RAVE-action: ' + action);
              return;
            }
            this.shinySetInput('@rave_action@', {
              type: action.type,
              details: action,
              element_class: evt.target.className
            }, true, true);
          } catch (e) {
            console.warn('Cannot parse RAVE-action: ' + action);
          }
        }
        return;
      }

      // .shidashi-button click → parse shidashi-action JSON
      const shidashiBtn = evt.target.closest('.shidashi-button[shidashi-action]');
      if (shidashiBtn) {
        if (shidashiBtn.classList.contains('disabled')) { return; }
        let action = shidashiBtn.getAttribute('shidashi-action');
        if (typeof action === 'string') {
          try {
            action = JSON.parse(action);
            if (typeof action.method === 'string' && typeof this[action.method] === 'function') {
              this[action.method].apply(this, action.args || []);
            }
          } catch (e) {}
        }
        return;
      }

      // Generic shidashi-button click (data-shidashi-action) → broadcast event to Shiny
      const shidashiDataBtn = evt.target.closest('[data-shidashi-action="shidashi-button"]');
      if (shidashiDataBtn) {
        evt.preventDefault();
        if (shidashiDataBtn.classList.contains('disabled')) { return; }
        const eventData = {};
        // Collect data-shidashi-* attributes as event payload
        for (const attr of shidashiDataBtn.attributes) {
          if (attr.name.startsWith('data-shidashi-') && attr.name !== 'data-shidashi-action') {
            const key = attr.name.replace('data-shidashi-', '');
            eventData[key] = attr.value;
          }
        }
        eventData.id = shidashiDataBtn.id || '';
        eventData.type = eventData.type || 'button.click';
        if (eventData.dynamic === "true") {
          eventData.message = Date.now();
        }
        this.broadcastEvent(eventData.type, eventData);
        return;
      }

      // .toggle-advance-options → toggle .rave-optional .soft-hidden
      const toggleBtn = evt.target.closest('.toggle-advance-options');
      if (toggleBtn) {
        const card = toggleBtn.closest('.card');
        if (card) {
          card.querySelectorAll('.rave-optional').forEach(el => {
            el.classList.toggle('soft-hidden');
          });
        }
        return;
      }

    });

    // Ctrl/Cmd + Enter → run_analysis
    document.addEventListener('keydown', (evt) => {
      if (evt.key === 'Enter' && (evt.ctrlKey || evt.metaKey)) {
        evt.preventDefault();
        this.shinySetInput('@rave_action@', {
          type: 'run_analysis'
        }, true, true);
      }
    });

    // Start-collapsed cards: after expand, remove start-collapsed class
    document.addEventListener('click', (evt) => {
      const collapseBtn = evt.target.closest('[data-card-widget="collapse"]');
      if (!collapseBtn) return;
      const card = collapseBtn.closest('.card.start-collapsed');
      if (!card) return;

      this.unbindAll(card);
      card.classList.remove('start-collapsed');
      this.bindAll(card);
    });

    // Theme toggle icon (sun/moon)
    const themeToggle = document.querySelector('[data-shidashi-action="theme-toggle"]');
    if (themeToggle) {
      themeToggle.addEventListener('click', (e) => {
        e.preventDefault();
        if (this.isDarkMode()) {
          this.asLightMode();
        } else {
          this.asDarkMode();
        }
      });
    }

    // Storage listener (cross-tab session sync)
    window.addEventListener('storage', (evt) => {
      if (evt.key !== this._keyNotification) return;
      const storage_key = this._storage_key;
      const private_id = this._private_id;
      if (!storage_key || !private_id) return;

      try {
        const item = JSON.parse(this._localStorage.getItem(this._keyNotification));
        const last_saved = new Date(item.last_saved);
        if (new Date() - last_saved < this._storageDuration) {
          if (item.storage_key === storage_key && private_id !== item.private_id) {
            this.ensureShiny(() => {
              this._shiny.onInputChange('@shidashi@', this._localStorage.getItem(storage_key));
            });
          }
        }
      } catch (e) {}
    });

    // Sidebar nav links → open iframe tab
    if (this.iframeManager && sidebarEl) {
      sidebarEl.addEventListener('click', (evt) => {
        const link = evt.target.closest('.shidashi-nav-link[href]');
        if (!link) return;
        // Skip group toggles (they have child treeview)
        if (link.parentElement?.classList.contains('shidashi-nav-group')) return;
        const href = link.getAttribute('href');
        if (!href || href === '#') return;
        evt.preventDefault();
        const title = link.getAttribute('title') || link.textContent.trim();
        this.iframeManager.openTab(href, title);
      });
    }

    // Tab change listener: report active tab name to Shiny input
    // In BS5, tab events are 'shown.bs.tab' on the nav-link element
    document.body.addEventListener('shown.bs.tab', (evt) => {
      const el = evt.target;
      const tablist = el.closest('[role="tablist"]');
      if (!tablist) return;
      const cardTabs = tablist.closest('.card-tabs');
      if (!cardTabs) return;
      if (!tablist.id) return;
      const tabname = el.textContent;
      this.ensureShiny((shiny) => {
        shiny.setInputValue(tablist.id, tabname);
      });
      this.broadcastEvent('tabset.activated', {
        tablistId: tablist.id,
        title: tabname
      });
    });

    // Report initial active tabs when Shiny becomes available
    // (queued via ensureShiny — will drain once shiny_connected is true)
    $(document).ready(() => {
      this.ensureShiny((shiny) => {
        const $tabLists = $('.card-tabs [role="tablist"]');
        for (let ii = 0; ii < $tabLists.length; ii++) {
          const pa = $tabLists[ii];
          if (pa && pa.id) {
            const activeTab = pa.querySelector('li.nav-item > .nav-link.active');
            if (activeTab) {
              shiny.setInputValue(pa.id, $(activeTab).text());
            }
          }
        }
      });
    });
  }

  _dismissPreloader() {
    const preloader = document.querySelector('.preloader');
    if (preloader && !preloader.classList.contains('preloader-hidden')) {
      preloader.classList.add('preloader-hidden');
    }
  }

  _initBackToTop() {
    const footerEl = document.querySelector('.ravedash-back-to-top');
    if (!footerEl) return;

    // ravedash generates data-toggle="tooltip" (BS3/4 style).
    // Migrate dropdown-toggle to BS5: set data-bs-toggle, fix aria.
    const dropdownToggle = footerEl.querySelector('.dropdown-toggle');
    if (dropdownToggle) {
      dropdownToggle.setAttribute('data-bs-toggle', 'dropdown');
      dropdownToggle.setAttribute('aria-haspopup', 'true');
      dropdownToggle.setAttribute('aria-expanded', 'false');

      // Initialise BS5 Dropdown if available
      if (window.bootstrap && window.bootstrap.Dropdown) {
        new bootstrap.Dropdown(dropdownToggle);
      }
    }

    // Migrate data-toggle="tooltip" → data-bs-toggle="tooltip" on all btns
    footerEl.querySelectorAll('[data-toggle="tooltip"]').forEach((el) => {
      el.setAttribute('data-bs-toggle', 'tooltip');
      el.removeAttribute('data-toggle');
      if (window.bootstrap && window.bootstrap.Tooltip) {
        new bootstrap.Tooltip(el);
      }
    });

    // Re-set the dropdown toggle back (tooltip migration may have overwritten it)
    if (dropdownToggle) {
      dropdownToggle.setAttribute('data-bs-toggle', 'dropdown');
    }

    // Populate the "Quick Access" section with shidashi-anchor items
    const menu = footerEl.querySelector('.dropdown-menu');
    const anchors = document.querySelectorAll('.shidashi-anchor');
    if (menu && anchors.length) {
      anchors.forEach((item) => {
        let itemId = item.getAttribute('id');
        if (typeof itemId !== 'string' || !itemId) {
          itemId = item.textContent.replace(/[^a-zA-Z0-9_-]/gi, '-').replace(/(--)/gi, '');
          itemId = 'shidashi-anchor-id-' + itemId;
          item.setAttribute('id', itemId);
        }
        const el = document.createElement('a');
        el.className = 'dropdown-item';
        el.href = '#' + itemId;
        el.textContent = item.textContent;
        menu.appendChild(el);
      });
    }

    // Scroll-to-top: the message button (btn-go-top) toggles the loader,
    // but if there's no rave-action we fall back to scroll-to-top.
    const gotopBtn = footerEl.querySelector('.btn-go-top:not([rave-action])');
    if (gotopBtn) {
      gotopBtn.addEventListener('click', () => this.scrollTop());
    }
  }

  // ---------- Custom drag-to-resize handles ----------

  _initResizeHandles() {
    const containers = document.querySelectorAll('.resize-vertical');
    if (!containers.length) return;

    containers.forEach((container) => {
      // Skip if already initialised
      if (container.querySelector('.shidashi-resize-handle')) return;

      const handle = document.createElement('div');
      handle.className = 'shidashi-resize-handle';
      container.appendChild(handle);

      let startY = 0;
      let startHeight = 0;

      const onMouseMove = (e) => {
        const delta = e.clientY - startY;
        const newHeight = Math.max(60, startHeight + delta);
        container.style.height = newHeight + 'px';
      };

      const onMouseUp = () => {
        handle.classList.remove('active');
        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUp);
        document.body.style.userSelect = '';
        document.body.style.cursor = '';
        this.triggerResize(50);
      };

      handle.addEventListener('mousedown', (e) => {
        e.preventDefault();
        startY = e.clientY;
        startHeight = container.offsetHeight;
        handle.classList.add('active');
        document.body.style.userSelect = 'none';
        document.body.style.cursor = 'ns-resize';
        document.addEventListener('mousemove', onMouseMove);
        document.addEventListener('mouseup', onMouseUp);
      });
    });

    // Horizontal resize handles: inject a drag handle into .resize-horizontal dividers
    document.querySelectorAll('.resize-horizontal').forEach((divider) => {
      // Skip if already initialised
      if (divider.querySelector('.shidashi-resize-handle-h')) return;

      const handle = document.createElement('div');
      handle.className = 'shidashi-resize-handle-h';
      divider.appendChild(handle);

      let startX = 0;
      let startWidthLeft = 0;
      let startWidthRight = 0;
      let leftEl = null;
      let rightEl = null;

      const onMouseMove = (e) => {
        const dx = e.clientX - startX;
        const totalWidth = startWidthLeft + startWidthRight;
        const newLeftWidth = Math.max(50, Math.min(totalWidth - 50, startWidthLeft + dx));
        const newRightWidth = totalWidth - newLeftWidth;
        leftEl.style.width = newLeftWidth + 'px';
        leftEl.style.flex = 'none';
        rightEl.style.width = newRightWidth + 'px';
        rightEl.style.flex = 'none';
      };

      const onMouseUp = () => {
        handle.classList.remove('active');
        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUp);
        document.body.style.userSelect = '';
        document.body.style.cursor = '';
        this.triggerResize(50);
      };

      divider.addEventListener('mousedown', (e) => {
        e.preventDefault();
        leftEl = divider.previousElementSibling;
        rightEl = divider.nextElementSibling;
        if (!leftEl || !rightEl) return;
        startX = e.clientX;
        startWidthLeft = leftEl.getBoundingClientRect().width;
        startWidthRight = rightEl.getBoundingClientRect().width;
        handle.classList.add('active');
        document.body.style.userSelect = 'none';
        document.body.style.cursor = 'col-resize';
        document.addEventListener('mousemove', onMouseMove);
        document.addEventListener('mouseup', onMouseUp);
      });
    });
  }

  // ---------- Drawer ----------

  drawerOpen() {
    // Drawer is always local to the current frame (module iframe)
    const drawer = document.querySelector('.shidashi-drawer');
    const overlay = document.querySelector('.shidashi-drawer-overlay');
    if (drawer) drawer.classList.add('open');
    if (overlay) overlay.classList.add('open');
    this.broadcastEvent('drawer.open', {});
  }

  drawerClose() {
    const drawer = document.querySelector('.shidashi-drawer');
    const overlay = document.querySelector('.shidashi-drawer-overlay');
    if (drawer) drawer.classList.remove('open');
    if (overlay) overlay.classList.remove('open');
    this.broadcastEvent('drawer.close', {});
  }

  drawerToggle() {
    const drawer = document.querySelector('.shidashi-drawer');
    if (drawer && drawer.classList.contains('open')) {
      this.drawerClose();
    } else {
      this.drawerOpen();
    }
  }

  // ---------- Register Shiny message handlers ----------

  _register_shiny() {
    if (!this._shiny) {
      if (window.Shiny) {
        this._shiny = window.Shiny;
      } else {
        console.error('Cannot find window.Shiny object. Is R-shiny running?');
        return false;
      }
    }
    if (this._shiny_registered) return;
    this._shiny_registered = true;

    this.shinyHandler('click', (params) => {
      this.click(params.selector);
    });

    this.shinyHandler('box_flip', (params) => {
      this.flipBox(params.inputId);
    });

    this.shinyHandler('card_tabset_insert', (params) => {
      const added = this.tabsetAdd(params.inputId, params.title, params.body, params.active);
      if (params.notify_on_failure === true && added !== true) {
        this.createNotification({
          autohide: true,
          delay: 2000,
          title: 'Cannot create new tab',
          body: added,
          class: 'bg-warning'
        });
      }
    });

    this.shinyHandler('card_tabset_remove', (params) => {
      const removed = this.tabsetRemove(params.inputId, params.title);
      if (params.notify_on_failure === true && removed !== true) {
        this.createNotification({
          autohide: true,
          delay: 2000,
          title: 'Cannot remove tab ' + params.title,
          body: removed,
          class: 'bg-warning'
        });
      }
    });

    this.shinyHandler('card_tabset_activate', (params) => {
      const activated = this.tabsetActivate(params.inputId, params.title);
      if (params.notify_on_failure === true && activated !== true) {
        this.createNotification({
          autohide: true,
          delay: 2000,
          title: 'Cannot activate tab ' + params.title,
          body: activated,
          class: 'bg-warning'
        });
      }
    });

    this.shinyHandler('cardwidget', (params) => {
      if (params.inputId) {
        // Direct id-based lookup
        const el = document.getElementById(params.inputId);
        if (el) {
          const card = el.closest('.card') || el;
          this._cardOperate(card, params.method);
        }
      } else if (params.title) {
        // Title-based lookup via data-title attribute
        const cards = document.querySelectorAll('.card[data-title]');
        for (const c of cards) {
          if (c.getAttribute('data-title') === params.title) {
            this._cardOperate(c, params.method);
            break;
          }
        }
      }
    });

    this.shinyHandler('card2widget', (params) => {
      this.toggleCard2(params.selector);
    });

    this.shinyHandler('add_attribute', (params) => {
      // params: { selector, attribute, value }
      if (params.selector && params.attribute) {
        document.querySelectorAll(params.selector).forEach(el => {
          el.setAttribute(params.attribute, params.value ?? '');
        });
      }
    });

    this.shinyHandler('remove_attribute', (params) => {
      // params: { selector, attribute }
      if (params.selector && params.attribute) {
        document.querySelectorAll(params.selector).forEach(el => {
          el.removeAttribute(params.attribute);
        });
      }
    });

    this.shinyHandler('drawer_open', (params) => {
      this.drawerOpen();
    });

    this.shinyHandler('drawer_close', (params) => {
      this.drawerClose();
    });

    this.shinyHandler('drawer_toggle', (params) => {
      this.drawerToggle();
    });

    // --- Activate a specific drawer tab (for chatbot) ---

    this.shinyHandler('activate_drawer_tab', (params) => {
      if (params.target) {
        const tabBtn = document.querySelector(
          `.shidashi-drawer-tabs [data-bs-target="${params.target}"]`
        );
        if (tabBtn && window.bootstrap && window.bootstrap.Tab) {
          const tab = new window.bootstrap.Tab(tabBtn);
          tab.show();
        }
      }
    });


    // --- AI agent pin toggle (sent only for modules with agent tools) ---

    this.shinyHandler('ai_pin_state', (params) => {
      this._setAiPinState(!!params.pinned);
    });

    // --- Module token registration (for chatbot) ---

    this.shinyHandler('register_module_token', (params) => {
      if (params.token) {
        this._sessionToken = params.token;
        // Re-report active module so R gets the updated token
        if (this._activeModuleId) {
          this._reportActiveModule(this._activeModuleId);
        }
      }
    });

    // --- Set Shiny input value from R (cross-session forwarding) ---

    this.shinyHandler('set_shiny_input', (params) => {
      // params: { inputId, value, priority }
      if (!params.inputId) return;
      const opts = params.priority === 'event' ? { priority: 'event' } : {};
      Shiny.setInputValue(params.inputId, params.value, opts);
    });

    // --- Output widget overlay (download/popout icons) ---

    this.shinyHandler('register_output_widgets', (params) => {
      // params: { outputId, widgets: ["download","popout"], download_type, token }
      const outputId = params.outputId;
      if (!outputId) return;

      const outputEl = document.getElementById(outputId);
      if (!outputEl) return;

      const parent = outputEl.parentElement;
      if (!parent) return;

      let container;

      if (parent.classList.contains('shidashi-output-widget-wrapper')) {
        container = parent.querySelector('.shidashi-output-widget-container');
      }

      if (!container) {
        parent.classList.add('shidashi-output-widget-wrapper');

        container = document.createElement('div');
        container.className = 'shidashi-output-widget-container';
        parent.insertBefore(container, outputEl);
      }

      const widgets = params.widgets || [];

      if (widgets.includes('download') && !container.querySelector('.shidashi-output-widget-icon[title="Download"]')) {
        const downloadBtn = document.createElement('a');
        downloadBtn.className = 'shidashi-output-widget-icon';
        downloadBtn.title = 'Download';
        downloadBtn.href = '#';
        downloadBtn.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" fill="currentColor" viewBox="0 0 16 16"><path d="M.5 9.9a.5.5 0 0 1 .5.5v2.5a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-2.5a.5.5 0 0 1 1 0v2.5a2 2 0 0 1-2 2H2a2 2 0 0 1-2-2v-2.5a.5.5 0 0 1 .5-.5"/><path d="M7.646 11.854a.5.5 0 0 0 .708 0l3-3a.5.5 0 0 0-.708-.708L8.5 10.293V1.5a.5.5 0 0 0-1 0v8.793L5.354 8.146a.5.5 0 1 0-.708.708z"/></svg>';
        downloadBtn.addEventListener('click', (e) => {
          e.preventDefault();
          if (window.Shiny) {
            Shiny.setInputValue(outputId + '__download_trigger', Date.now(), { priority: 'event' });
          }
        });
        container.appendChild(downloadBtn);
      }

      if (widgets.includes('popout') && !container.querySelector('.shidashi-output-widget-icon[title="Open in new window"]')) {
        const popoutBtn = document.createElement('a');
        popoutBtn.className = 'shidashi-output-widget-icon';
        popoutBtn.title = 'Open in new window';
        popoutBtn.href = '#';
        popoutBtn.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" fill="currentColor" viewBox="0 0 16 16"><path fill-rule="evenodd" d="M8.636 3.5a.5.5 0 0 0-.5-.5H1.5A1.5 1.5 0 0 0 0 4.5v10A1.5 1.5 0 0 0 1.5 16h10a1.5 1.5 0 0 0 1.5-1.5V7.864a.5.5 0 0 0-1 0V14.5a.5.5 0 0 1-.5.5h-10a.5.5 0 0 1-.5-.5v-10a.5.5 0 0 1 .5-.5h6.636a.5.5 0 0 0 .5-.5"/><path fill-rule="evenodd" d="M16 .5a.5.5 0 0 0-.5-.5h-5a.5.5 0 0 0 0 1h3.793L6.146 9.146a.5.5 0 1 0 .708.708L15 1.707V5.5a.5.5 0 0 0 1 0z"/></svg>';
        popoutBtn.addEventListener('click', (e) => {
          e.preventDefault();
          const token = this._sessionToken || '';
          window.open('?module=standalone_viewer&outputId=' + encodeURIComponent(outputId) + '&token=' + encodeURIComponent(token));
        });
        container.appendChild(popoutBtn);
      }
    });

    // --- Chatbot status bar handler ---

    this.shinyHandler('update_chat_status', (params) => {
      // params: { id, text, title?, status: "ready"|"recalculating"|"unknown" }
      const el = document.getElementById(params.id);
      if (!el) return;
      if (params.text !== undefined) {
        el.textContent = params.text;
      }
      if (params.title !== undefined) {
        el.setAttribute('title', params.title);
      }
      // Toggle recalculating blink
      el.classList.toggle(
        'shidashi-chatbot-status-recalculating',
        params.status === 'recalculating'
      );
      // Mark unknown cost with strikethrough
      el.classList.toggle(
        'shidashi-chatbot-status-unknown',
        params.status === 'unknown'
      );
    });

    // --- Chatbot stop button initialization ---

    this.shinyHandler('init_chat_stop_button', (params) => {
      // params: { chat_id, stop_id }
      const chatContainer = document.getElementById(params.chat_id);
      if (!chatContainer) return;

      const chatInput = chatContainer.querySelector('shiny-chat-input');
      if (!chatInput) return;

      // Don't create if already exists
      if (document.getElementById(params.stop_id)) return;

      // Create stop button - styles defined in shidashi.scss
      const stopBtn = document.createElement('button');
      stopBtn.type = 'button';
      stopBtn.id = params.stop_id;
      stopBtn.className = 'shidashi-chatbot-stop';
      stopBtn.title = 'Stop generation';
      stopBtn.setAttribute('aria-label', 'Stop generation');
      stopBtn.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" viewBox="0 0 16 16">
        <path d="M16 8A8 8 0 1 1 0 8a8 8 0 0 1 16 0M6.5 5A1.5 1.5 0 0 0 5 6.5v3A1.5 1.5 0 0 0 6.5 11h3A1.5 1.5 0 0 0 11 9.5v-3A1.5 1.5 0 0 0 9.5 5z"/>
      </svg>`;

      // Insert into the chat input container
      chatInput.style.position = 'relative';
      chatInput.appendChild(stopBtn);

      // Bind Shiny input - increment counter on click
      stopBtn.addEventListener('click', () => {
        if (window.Shiny) {
          const currentVal = Shiny.shinyapp.$inputValues[params.stop_id] || 0;
          Shiny.setInputValue(params.stop_id, currentVal + 1, { priority: 'event' });
        }
      });
    });

    // --- Chatbot stop button toggle ---

    this.shinyHandler('toggle_stop_button', (params) => {
      // params: { id, visible }
      const el = document.getElementById(params.id);
      if (!el) return;
      // Toggle visibility via CSS class
      el.classList.toggle('shidashi-chatbot-stop-visible', params.visible);
    });

    // --- Query UI handler (MCP) ---

    this.shinyHandler('prepare_output', (params) => {
      // params: { selector, request_id, input_id, needs_size }
      // Step 1 of `shiny_output_result`: find the output, and give it a
      // size if it has never been shown (shiny sizes plots from the browser)
      const selector = params.selector;
      const requestId = params.request_id;
      const inputId = params.input_id;
      if (!selector || !requestId || !inputId) return;

      const reply = (fields) => {
        Shiny.setInputValue(inputId, Object.assign({
          request_id: requestId,
          type: 'prepared',
          note: ''
        }, fields), { priority: 'event' });
      };

      const el = document.querySelector(selector);
      if (!el) {
        reply({ type: 'not_found', note: "No element matched selector: '" + selector + "'" });
        return;
      }

      const rect = el.getBoundingClientRect();
      const reportsSize = el.classList.contains('shiny-plot-output') ||
        el.classList.contains('shiny-image-output') ||
        el.classList.contains('shiny-report-size');
      let fallbackSize = null;
      if (params.needs_size && reportsSize && el.id &&
          rect.width === 0 && rect.height === 0) {
        fallbackSize = this._fallbackOutputSize(el);
        // Sent before the reply, so R has the size before the output runs;
        // shiny sends the real size once the output is shown
        Shiny.setInputValue('.clientdata_output_' + el.id + '_width', fallbackSize.width);
        Shiny.setInputValue('.clientdata_output_' + el.id + '_height', fallbackSize.height);
      }
      reply({ laid_out: el.getClientRects().length > 0, fallback_size: fallbackSize });
    });

    this.shinyHandler('query_ui', (params) => {
      // params: { selector, request_id, input_id, transform_image, wait_ms }
      const selector = params.selector;
      const requestId = params.request_id;
      const inputId = params.input_id;
      if (!selector || !requestId || !inputId) return;

      const el = document.querySelector(selector);
      if (!el) {
        Shiny.setInputValue(inputId, {
          request_id: requestId,
          type: 'not_found',
          note: "No element matched selector: '" + selector + "'"
        }, { priority: 'event' });
        return;
      }

      // With `wait_ms`, answer once the output has finished recalculating
      const waitMs = Number(params.wait_ms) || 0;
      if (waitMs > 0 && el.classList.contains('recalculating')) {
        this._waitRecalculated(el, waitMs).then(() => {
          this._answerQuery(el, params);
        });
        return;
      }
      this._answerQuery(el, params);
    });

    this.shinyHandler('show_notification', (params) => {
      this.createNotification(params);
    });

    this.shinyHandler('clear_notification', (params) => {
      this.clearNotification(params.selector);
    });

    this.shinyHandler('set_progress', (params) => {
      this.setProgress(params.outputId, params.value, params.max || 100, params.description);
    });

    this.shinyHandler('make_scroll_fancy', (params) => {
      // No-op: using CSS native scrollbars instead of OverlayScrollbars
      // Keeping handler registered so R calls don't error
    });

    this.shinyHandler('cache_session_input', (params) => {
      this.sessionData = params.inputs;
      this.broadcastSessionData(params.shared_id, params.private_id);
    });

    this.shinyHandler('get_theme', (params) => {
      this._reportTheme();
    });

    this.shinyHandler('reset_output', (params) => {
      const el = document.getElementById(params.outputId);
      if (el && el.parentElement) {
        this.ensureShiny((shiny) => {
          const $parentEl = $(el.parentElement);
          Object.keys(shiny.outputBindings.bindingNames).forEach((key) => {
            const binding = shiny.outputBindings.bindingNames[key].binding;
            if (binding && typeof binding.find === 'function') {
              $(binding.find($parentEl)).each(function() {
                if (this.id === el.id) {
                  binding.renderError(el, {
                    message: params.message || '',
                    type: 'shiny-output-error-shiny.silent.error shiny-output-error-validation'
                  });
                }
              });
            }
          });
        });
      }
    });

    // --- Additional handlers used by ravedash ---

    this.shinyHandler('set_current_module', (params) => {
      this._moduleId = params.module_id;
      this._active_module = params.module_id;
      this._sessionToken = params.shiny_token || "";
      if (this.sidebar && params.module_id) {
        this.sidebar.setActiveByModule(params.module_id);
      }
      if (this.iframeManager && params.module_id) {
        this.iframeManager.openTabByModule(params.module_id, params.title);
      }
      // Report active module even when there is no iframe manager
      if (params.module_id) {
        this._reportActiveModule(params.module_id);
      }
    });

    this.shinyHandler('switch_module', (params) => {
      // params: { module_id, auto_new, request_id, input_id }. With
      // `request_id` (the `switch_module` MCP tool), the status goes back to
      // R through the input `input_id`
      if (!params.module_id) return;
      const app = this._dashboardApp();
      const status = app
        ? app.switchModule(params.module_id, params.auto_new !== false)
        : 'no_dashboard';
      if (params.request_id && params.input_id) {
        Shiny.setInputValue(params.input_id, {
          request_id: params.request_id,
          status: status
        }, { priority: 'event' });
      }
    });

    this.shinyHandler('hide_header', (params) => {
      this.addClass('body', 'navbar-hidden');
      this.notifyParent('addClass', ['body', 'navbar-hidden']);
    });

    this.shinyHandler('show_header', (params) => {
      this.removeClass('body', 'navbar-hidden');
      this.notifyParent('removeClass', ['body', 'navbar-hidden']);
    });

    this.shinyHandler('open_url', (params) => {
      if (params && typeof params === 'object' && typeof params.url === 'string') {
        const target = params.target || '_blank';
        this.openURL(params.url, target);
      }
    });

    this.shinyHandler('shutdown_session', (params) => {
      // Close the window or navigate away
      if (params.url) {
        window.location.href = params.url;
      } else {
        window.close();
      }
    });

    this.shinyHandler('open_iframe_tab', (params) => {
      if (this.iframeManager) {
        this.iframeManager.openTab(params.url, params.title || 'Module');
      }
    });

    this.shinyHandler('set_html', (params) => {
      if (params.selector) {
        const els = document.querySelectorAll(params.selector);
        els.forEach(el => {
          if (params.content !== undefined) {
            this.unbindAll(el, false);
            if (params.is_text) {
              el.textContent = params.content;
            } else {
              el.innerHTML = params.content;
            }
            this.bindAll(el, false);
          }
        });
      }
    });

    this.shinyHandler('accordion', (params) => {
      if (!params.selector) return;
      const el = document.querySelector(params.selector);
      if (!el) return;
      const method = params.method || 'toggle';
      if (method === 'expand') {
        if (el.classList.contains('collapsed')) { el.click(); }
      } else if (method === 'collapse') {
        if (!el.classList.contains('collapsed')) { el.click(); }
      } else {
        el.click();
      }
    });

    this.shinyHandler('add_class', (params) => {
      if (params.selector && params.class) {
        this.addClass(params.selector, params.class);
      }
    });

    this.shinyHandler('remove_class', (params) => {
      if (params.selector && params.class) {
        this.removeClass(params.selector, params.class);
      }
    });

    // --- Ask-user handler (MCP built-in tool) ---

    this.shinyHandler('ask_user', (params) => {
      // params: { request_id, input_id, message, choices, allow_freeform }
      const requestId = params.request_id;
      const inputId = params.input_id;
      if (!requestId || !inputId) return;

      const message = params.message || 'The agent needs your input:';
      const choices = params.choices || [];
      const allowFreeform = params.allow_freeform !== false;

      // Build a Bootstrap 5 modal
      const modalId = 'shidashi-ask-user-modal-' + requestId;
      const existing = document.getElementById(modalId);
      if (existing) existing.remove();

      let bodyHTML;
      if (params.tool_name) {
        bodyHTML = `<p class="mb-3">The agent wants to call tool <code>${this._escapeHtml(params.tool_name)}</code>.${
          params.intent ? ' Reason:' : ''
        }</p>`;
        if (params.intent) {
          bodyHTML += `<p class="mb-3"><em>${this._escapeHtml(params.intent)}</em></p>`;
        }
        bodyHTML += `<p class="mb-3">${this._escapeHtml(message)}</p>`;
      } else {
        bodyHTML = `<p class="mb-3">${this._escapeHtml(message)}</p>`;
      }

      // Choice buttons
      if (choices.length > 0) {
        bodyHTML += '<div class="d-flex flex-wrap gap-2 mb-3">';
        choices.forEach((choice, i) => {
          bodyHTML += `<button type="button" class="btn btn-outline-primary shidashi-ask-user-choice" data-choice-index="${i}">${this._escapeHtml(choice)}</button>`;
        });
        bodyHTML += '</div>';
      }

      // Free-form input
      if (allowFreeform) {
        bodyHTML += `<div class="mb-2"><textarea class="form-control shidashi-ask-user-freeform" rows="3" placeholder="Type your response..."></textarea></div>`;
      }

      const modalHTML = `
        <div class="modal fade" id="${modalId}" tabindex="-1" data-bs-backdrop="static" data-bs-keyboard="false">
          <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
              <div class="modal-header">
                <h5 class="modal-title">Agent Request</h5>
              </div>
              <div class="modal-body">${bodyHTML}</div>
              <div class="modal-footer">
                ${allowFreeform ? '<button type="button" class="btn btn-primary shidashi-ask-user-submit" disabled>Submit</button>' : ''}
                <button type="button" class="btn btn-secondary shidashi-ask-user-cancel">Cancel</button>
              </div>
            </div>
          </div>
        </div>`;

      document.body.insertAdjacentHTML('beforeend', modalHTML);
      const modalEl = document.getElementById(modalId);
      const bsModal = new bootstrap.Modal(modalEl);

      const respond = (value, cancelled) => {
        Shiny.setInputValue(inputId, {
          request_id: requestId,
          value: value,
          cancelled: !!cancelled
        }, { priority: 'event' });
        bsModal.hide();
        modalEl.addEventListener('hidden.bs.modal', () => modalEl.remove(), { once: true });
      };

      // Choice button clicks
      modalEl.querySelectorAll('.shidashi-ask-user-choice').forEach(btn => {
        btn.addEventListener('click', () => {
          const idx = parseInt(btn.dataset.choiceIndex, 10);
          respond(choices[idx], false);
        });
      });

      // Free-form submit
      const submitBtn = modalEl.querySelector('.shidashi-ask-user-submit');
      const textarea = modalEl.querySelector('.shidashi-ask-user-freeform');
      if (submitBtn && textarea) {
        textarea.addEventListener('input', () => {
          submitBtn.disabled = !textarea.value.trim();
        });
        submitBtn.addEventListener('click', () => {
          respond(textarea.value.trim(), false);
        });
      }

      // Cancel
      modalEl.querySelector('.shidashi-ask-user-cancel').addEventListener('click', () => {
        respond(null, true);
      });

      bsModal.show();

      // Focus textarea if present
      if (textarea) {
        modalEl.addEventListener('shown.bs.modal', () => textarea.focus(), { once: true });
      }
    });

    // --- Initialize code copy buttons for a chat container ---

    this.shinyHandler('init_chat_code_copy', (params) => {
      // params: { chat_id }
      const chatContainer = document.getElementById(params.chat_id);
      if (!chatContainer) return;

      // Don't re-initialize
      if (chatContainer._shidashiCodeCopyInit) return;
      chatContainer._shidashiCodeCopyInit = true;

      // Initialize ClipboardJS on copy-conversation button
      const copyConvBtn = document.querySelector(
        `[data-shidashi-action="copy-conversation"][data-shidashi-chat-id="${params.chat_id}"]`
      );
      if (copyConvBtn && !copyConvBtn._clipboardInit) {
        copyConvBtn._clipboardInit = true;
        const chatId = params.chat_id; // Capture in closure
        const clipboard = new ClipboardJS(copyConvBtn, {
          text: () => getConversationMarkdown(chatId)
        });
        clipboard.on('success', (e) => {
          e.clearSelection();
          showToast('Conversation copied to clipboard');
        });
      }

      // Inject copy buttons into existing code blocks
      injectCodeCopyButtons(chatContainer);

      // Watch for new code blocks (chat responses are added dynamically)
      const observer = new MutationObserver((mutations) => {
        mutations.forEach(mutation => {
          mutation.addedNodes.forEach(node => {
            if (node.nodeType === Node.ELEMENT_NODE) {
              injectCodeCopyButtons(node);
            }
          });
        });
      });
      observer.observe(chatContainer, { childList: true, subtree: true });
    });

    // Hide toasts with .hide-on-shiny-idle class when Shiny goes idle
    $(document).on('shiny:idle', () => {
      document.querySelectorAll('.toast.hide-on-shiny-idle').forEach(el => {
        if (window.bootstrap?.Toast) {
          const instance = bootstrap.Toast.getInstance(el);
          if (instance) { instance.hide(); return; }
        }
        el.remove();
      });
    });
  }
}

// ============================================================================
// Bootstrap
// ============================================================================

// Create global instance immediately
window.shidashi = new ShidashiApp();

// Initialize when DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', _init);
} else {
  _init();
}

function _init() {
  registerOutputBindings();
  window.shidashi._finalize_initialization();

  // Register shiny handlers when shiny connects
  // NOTE: 'shiny:connected' is a jQuery custom event, must use $(document).on()
  $(document).on('shiny:connected', () => {
    // 1. Register all message handlers first
    window.shidashi._register_shiny();
    // 2. NOW mark as connected and drain the queue
    window.shidashi.shiny_connected = true;
    window.shidashi.ensureShiny();
    // 3. Dismiss preloader now that Shiny is ready
    window.shidashi._dismissPreloader();
  });
}

// Highlight.js initialization (if loaded)
if (window.hljs) {
  window.hljs.configure({ languages: [] });
  if (typeof window.hljs.highlightAll === 'function') {
    window.hljs.highlightAll();
  } else if (typeof window.hljs.initHighlightingOnLoad === 'function') {
    window.hljs.initHighlightingOnLoad();
  }
}
